import{z as t,x as i,o as E,c as n,q as r,j as o,D as e,d as l,s as A,S as B}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"寄存器分配的深入","description":"","frontmatter":{"title":"寄存器分配的深入","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cg-register-allocation-deep.md","filePath":"cs/cg-register-allocation-deep.md","lastUpdated":1791413859000}'),d={name:"cs/cg-register-allocation-deep.md"};function p(c,a,h,C,D,_){const s=i("Mermaid");return E(),n("div",null,[a[2]||(a[2]=r('<h1 id="寄存器分配的深入" tabindex="-1">寄存器分配的深入 <a class="header-anchor" href="#寄存器分配的深入" aria-label="Permalink to &quot;寄存器分配的深入&quot;">​</a></h1><div class="epigraph"><p>寄存器分配不是把变量搬进格子，而是在一台比程序需要的更小的物理机上安排搬迁；代价表错了，搬得越勤快，程序越慢。</p><footer>—— 据 Chow and Hennessy, ACM TOPLAS, 1984；Briggs, Cooper and Torczon, PLDI, 1992 整理</footer></div><p><a href="/cs/obs-map">上一课</a>给「可观测性与调试」收束：埋点、检测、止损、复盘、加固是一条闭环，预算先行、证据分层、回路闭合三句口诀各管一类错误——系统跑错时怎么看见已经答完，程序被错译或漏优化时怎么看见，是另一门手艺。加上更早的<a href="/cs/regalloc-color">着色分配</a>、<a href="/cs/linear-scan-regalloc">线性扫描</a>与 <a href="/cs/chaitin-briggs">Chaitin–Briggs 一族</a>，机制件齐了。缺的是决策层：真实函数里，溢出什么、溢出成什么样、在哪拆，三个决定互相纠缠，还把后果反馈回压力本身。本课是「编译器后端深化」的第一课，把这层决策补成一张能算的账；本课程后面的选择、调度、链接、JIT 与 MLIR，都默认你已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干给出的流程是单步的：建冲突图、简化、溢出、改写、重来。每步单独都对，连起来却没人回答三个问题。第一，溢出谁：图上每个节点的度数一样，代价不一样——最内层循环里的一次使用与循环外的一次使用，相差几个数量级。第二，溢出成什么样：<a href="/cs/spill-remat">溢出与重物化</a>给过两种改写，但没有给「选哪个」的判据。第三，在哪拆：把一个跨循环的长区间整个溢出，等于让循环外便宜的部分陪绑。没有代价表，这些全是抽签；抽错一次，热点循环里就多出一对 store/load，每次迭代都付。</p><h3 id="代价怎么算" tabindex="-1">代价怎么算 <a class="header-anchor" href="#代价怎么算" aria-label="Permalink to &quot;代价怎么算&quot;">​</a></h3><p>第一个能算的量是嵌套权重：给每个使用点记 \\(10^{d}\\)，\\(d\\) 是它所在循环的嵌套深度，顶层一次用是 \\(1\\)，三层循环里的一次用是 \\(1000\\)。区间代价近似为各使用点权重之和。Chow–Hennessy 的优先级着色用「每单位邻居度数的代价」排序：先保贵的，先溢便宜的。静态分支频度与代码布局给冷路径折价，这张表的底数是估计——但指数权重保证估计错一倍，也不至于把内层循环错当成外层。</p><p><span class="marginnote">数字实例：把一个值溢出到内层循环里，一次 load 权重按 \\(10^3 = 1000\\) 计——等价于顶层代码里一千次使用。这意味着哪怕估计器把循环次数估错十倍，也只是把「1000」算成「100」，排序结论通常不变：内层的值无论如何该留在寄存器。</span></p><p><span class="marginnote">Chow–Hennessy 的指数权重：嵌套深度每加一层，使用点权重乘十。溢出槽几乎总该留在循环外，是这张代价表最直接的推论；同理，重物化放在内层才划算，放在冷路径上常常不值得省那个栈槽。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>有了代价表，三种改写才能排序。溢出最贵：定义点一次 store、每个使用点一次 load，按使用点权重计价。重物化次之：定义本身廉价时——立即数、几条地址算术——在使用点重算比 round-trip 便宜，还不占栈槽。拆分最便宜但最细：把长区间在压力谷处切成两段，贵的一段留寄存器，便宜的一段落槽；拆分点常选在支配边界上，<a href="/cs/dominator-phi">支配与 φ</a> 的语言在这里直接用上。</p>',11)),(E(),o(B,null,{default:e(()=>[A(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20VAL%5B%22%E4%B8%80%E4%B8%AA%E5%BF%85%E9%A1%BB%E8%AE%A9%E4%BD%8D%E7%9A%84%E5%8C%BA%E9%97%B4%22%5D%20--%3E%20Q%7B%22%E6%94%B9%E5%86%99%E9%80%89%E5%93%AA%E7%A7%8D%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%BA%A2%E5%87%BA%22%7C%20SP%5B%22%E5%AE%9A%E4%B9%89%E7%82%B9%20store%20%2B%20%E6%AF%8F%E4%B8%AA%E4%BD%BF%E7%94%A8%E7%82%B9%20load%22%5D%0A%20%20Q%20--%3E%7C%22%E9%87%8D%E7%89%A9%E5%8C%96%22%7C%20RM%5B%22%E4%B8%8D%E4%BF%9D%E5%AD%98%EF%BC%9A%E4%BD%BF%E7%94%A8%E7%82%B9%E9%87%8D%E7%AE%97%E4%B8%80%E9%81%8D%22%5D%0A%20%20Q%20--%3E%7C%22%E6%8B%86%E5%88%86%22%7C%20SPLIT%5B%22%E5%8E%8B%E5%8A%9B%E8%B0%B7%E5%A4%84%E5%88%87%E4%B8%A4%E6%AE%B5%EF%BC%9A%E8%B4%B5%E6%AE%B5%E7%95%99%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20SP%20--%3E%20BILL%5B%22%E8%AE%A1%E4%BB%B7%EF%BC%9A%E4%BD%BF%E7%94%A8%E7%82%B9%E6%9D%83%E9%87%8D%E6%B1%82%E5%92%8C%22%5D%0A%20%20RM%20--%3E%20BILL2%5B%22%E8%AE%A1%E4%BB%B7%EF%BC%9A%E5%AE%9A%E4%B9%89%E6%88%90%E6%9C%AC%20%C3%97%20%E4%BD%BF%E7%94%A8%E6%AC%A1%E6%95%B0%22%5D%0A%20%20SPLIT%20--%3E%20BILL3%5B%22%E8%AE%A1%E4%BB%B7%EF%BC%9A%E5%8F%AA%E4%BB%98%E4%BE%BF%E5%AE%9C%E6%AE%B5%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">术语翻译：重物化（rematerialization）就是「不保存，用时重算」——比如一个常量或「某数组首地址加偏移」这类几条指令就能重建的值，与其 store 到栈里再 load 回来，不如在使用点重新算一遍，还省一个栈槽。</span></p><p>SSA 上还有一条捷径。SSA 形式的干涉图是弦图，弦图有完美消去序，\\(K\\)-着色不再需要启发式猜测；工程上的 SSA 型分配器干脆把溢出统一推迟成「处处溢出」的一次性改写，再由 <a href="/cs/ssa-destruction">SSA 析构</a>接住。主干里的着色启发式是给一般控制流的；拿到 SSA 就不必再付那笔启发式的钱。</p><p><a href="/cs/abi-codegen">ABI</a> 从两侧夹住分配：预着色节点钉住调用点两侧的实参与返回值寄存器；callee-saved 用一个赔一个，prologue 里 push 的列表就是分配的下游账单。所以工程实现常把 callee-saved 留作缓冲：先用 caller-saved，不够再动「要赔钱」的那批。</p><p><span class="marginnote">直觉类比：caller-saved 寄存器像出租车——下车（调用别人）就两清，里面有没有行李自己事先拿走；callee-saved 像借朋友的车——朋友（被调方）用完必须原样还，还要替你保管（push/pop）。所以调用密集处优先用出租车，朋友的车留给整个函数都活得久的值。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2>',5)),(E(),o(B,null,{default:e(()=>[A(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIVE%5B%22%E6%B4%BB%E8%B7%83%E6%80%A7%E5%88%86%E6%9E%90%22%5D%20--%3E%20COST%5B%22%E4%BB%A3%E4%BB%B7%E8%A1%A8%EF%BC%9A%E5%B5%8C%E5%A5%97%E6%9D%83%E9%87%8D%22%5D%0A%20%20COST%20--%3E%20ALLOC%5B%22%E7%9D%80%E8%89%B2%20%2F%20%E5%8C%BA%E9%97%B4%E5%88%86%E9%85%8D%22%5D%0A%20%20ALLOC%20--%3E%20SPILL%7B%22%E6%9C%89%E6%BA%A2%E5%87%BA%EF%BC%9F%22%7D%0A%20%20SPILL%20--%3E%7C%E6%97%A0%7C%20DONE%5B%22%E8%BE%93%E5%87%BA%E7%89%A9%E7%90%86%E5%88%86%E9%85%8D%22%5D%0A%20%20SPILL%20--%3E%7C%E6%9C%89%7C%20REW%5B%22%E6%94%B9%E5%86%99%EF%BC%9A%E6%BA%A2%E5%87%BA%20%2F%20%E9%87%8D%E7%89%A9%E5%8C%96%20%2F%20%E6%8B%86%E5%88%86%22%5D%0A%20%20REW%20--%3E%20LIVE%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p>单步流程连成不动点：每次改写产生新 IR，新 IR 要重做<a href="/cs/dataflow-liveness">活跃性分析</a>、重建图、再分配，直到无溢出。两个工程后果由此而来。其一，<a href="/cs/coalescing-splitting">迭代合并</a>之所以保守——只合并那些合并后干涉图仍可着色的邻居对——是因为激进合并推高压力，把分配推回不动点的下一圈，省下的 mov 会在别处以溢出付回去。其二，分配前值得做一次前置压力扫描：如果热点块的寄存器需求本来就超过 \\(K\\)，任何分配器都救不了，该回头缩短区间，而不是让后端硬吃。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲着色与扫描的机制，也不处理物理寄存器堆的异构——x87 栈与通用寄存器之间的搬移是另一层约束。硬件侧的<a href="/cs/register-renaming">寄存器重命名</a>在乱序核内部另设物理寄存器消假依赖；那是同一个「名字不够用」问题在硬件里的解，编译器看不见，不能拿它当借口。分配与调度的耦合——藏延迟会把区间拉长、压力推高——留给本课程后面的调度课处理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分配的深层不是建图，而是代价表：嵌套指数权重让「溢出谁」可算。</li><li>三种改写有价序：拆分、重物化、溢出；贵贱由使用点权重与定义成本决定。</li><li>SSA 把着色降为弦图上的多项式问题，溢出推迟成统一改写。</li><li>合并、溢出与压力互相反馈：分配是改写—重建的不动点，不是一遍。</li><li>出处：Chow and Hennessy, 1984；Briggs, Cooper and Torczon, 1992；George and Appel, 1996；Hack 的 SSA 寄存器分配工作。</li></ul>',5))])}const f=t(d,[["render",p]]);export{S as __pageData,f as default};
